#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long target;
    cin >> n >> target;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    int l = 0, rr = n - 1;
    while (l < rr) {
        long long s = a[l] + a[rr];
        if (s == target) break;
        if (s < target) l++;
        else rr--;
    }
    cout << l + 1 << " " << rr + 1 << "\n";

    return 0;
}

